// MachineUsageReceiptDto defines model for MachineUsageReceiptDto.
type MachineUsageReceiptDto struct {
	AssignmentGeneration int                `json:"assignmentGeneration"`
	Cpu                  int                `json:"cpu"`
	DiskGiB              int                `json:"diskGiB"`
	FencingToken         openapi_types.UUID `json:"fencingToken"`
	GenerationId         openapi_types.UUID `json:"generationId"`
	Gpu                  int                `json:"gpu"`

	// HostEgressBytes Cumulative bytes the guest sent to the host, which relays Edge exposure responses
	HostEgressBytes string `json:"hostEgressBytes"`

	// HostIngressBytes Cumulative bytes the host sent to the guest, which relays Edge exposure requests
	HostIngressBytes string `json:"hostIngressBytes"`

	// InternetEgressBytes Cumulative bytes the guest sent to the internet in the runtime generation (billable egress candidate)
	InternetEgressBytes string `json:"internetEgressBytes"`

	// InternetIngressBytes Cumulative bytes the guest received on connections it opened to the internet in the runtime generation
	InternetIngressBytes string             `json:"internetIngressBytes"`
	MemoryGiB            int                `json:"memoryGiB"`
	PlacementId          openapi_types.UUID `json:"placementId"`

	// PreviousDigest Payload digest of the previous reading in the placement runtime generation, or 64 zeros for its first reading
	PreviousDigest string `json:"previousDigest"`

	// RunningMillis Cumulative milliseconds the runtime spent started in its generation
	RunningMillis string    `json:"runningMillis"`
	SampledAt     time.Time `json:"sampledAt"`
	SandboxId     string    `json:"sandboxId"`

	// Sequence Monotonic unsigned sequence in the runtime generation
	Sequence string `json:"sequence"`

	// Signature Ed25519 signature encoded as unpadded base64url
	Signature string                   `json:"signature"`
	State     MachineUsageRuntimeState `json:"state"`

	// TapEgressBytes Cumulative frame bytes the guest transmitted on its TAP device
	TapEgressBytes string `json:"tapEgressBytes"`

	// TapIngressBytes Cumulative frame bytes the guest received on its TAP device
	TapIngressBytes string `json:"tapIngressBytes"`
}

